	.@map$ = getarg(0);
	.@id_min = getarg(1);
	.@id_max = getarg(2);
	.@amount = getarg(3);

	for ( .@i = .@id_min; .@i <= .@id_max; ++.@i )
		monster .@map$,0,0,"--ja--",.@i,.@amount, "control_t_garden::OnMob" + .@i;
	return;

